// Core static analysis: registry/inheritance, entry points, reachability
// via the intra-contract call graph, and the three audit rules.

export const RULES = {
  DELEGATECALL_UNTRUSTED_TARGET: { severity: 'high' },
  UNCHECKED_EXTERNAL_CALL: { severity: 'medium' },
  STATE_UPDATE_AFTER_CALL: { severity: 'high' },
};

const LOW_LEVEL_CALLS = new Set(['call', 'staticcall', 'send', 'transfer']);
const DELEGATE_CALLS = new Set(['delegatecall']);
const ALL_LOW_LEVEL = new Set([...LOW_LEVEL_CALLS, ...DELEGATE_CALLS]);
const BUILTIN_CALLS = new Set([
  'require', 'assert', 'revert', 'keccak256', 'sha256', 'ripemd160',
  'ecrecover', 'addmod', 'mulmod', 'blockhash', 'selfdestruct', 'suicide',
  'gasleft', 'blake2f160', 'modexp', 'ecadd', 'ecmul', 'ecpairing',
]);

const PRIMITIVE_TYPES = new Set([
  'bool', 'string', 'bytes', 'address', 'payable', 'var',
  'uint', 'int', 'byte', 'tuple',
]);

function isPrimitiveType(typeNode) {
  if (!typeNode) return true;
  if (typeNode.kind === 'typeMapping' || typeNode.kind === 'typeArray') return false;
  if (typeNode.kind === 'typeFunction') return false;
  const head = typeNode.path[0];
  if (head === 'address') return true;
  if (/^u?int\d*$/.test(head)) return true;
  if (/^bytes\d*$/.test(head)) return true;
  return PRIMITIVE_TYPES.has(head);
}

// ---- descriptors -----------------------------------------------------------

function methodKey(name, arity) { return `${name}/${arity}`; }
function descKey(d) { return `${d.file}::${d.contract || ''}::${d.kind}:${d.name}/${d.arity}`; }
function entryKey(d) { return `${d.contract || ''}:${d.kind}:${d.name}/${d.arity}`; }

function descriptorFor(node, file, contractName, arity) {
  return {
    file,
    contract: contractName,
    name: node.functionKind === 'function' ? node.name : node.functionKind,
    kind: node.functionKind,
    arity,
    visibility: node.visibility,
  };
}

// ---- expression / statement walking ----------------------------------------

function walkExpr(node, cb) {
  if (!node || typeof node !== 'object') return;
  cb(node);
  switch (node.kind) {
    case 'binary': walkExpr(node.left, cb); walkExpr(node.right, cb); break;
    case 'unary': walkExpr(node.operand, cb); break;
    case 'assign': walkExpr(node.target, cb); walkExpr(node.value, cb); break;
    case 'conditional': walkExpr(node.test, cb); walkExpr(node.cons, cb); walkExpr(node.alt, cb); break;
    case 'member': walkExpr(node.object, cb); break;
    case 'index': walkExpr(node.object, cb); walkExpr(node.index, cb); break;
    case 'call':
      walkExpr(node.callee, cb);
      for (const a of node.args || []) walkExpr(a, cb);
      for (const o of node.options || []) walkExpr(o.value, cb);
      break;
    case 'tuple': for (const it of node.items || []) walkExpr(it, cb); break;
    case 'newExpr': walkExpr(node.typeNode, cb); break;
    case 'structLiteral': for (const f of node.fields || []) walkExpr(f.value, cb); break;
    default: break;
  }
}

const SKIP = Symbol('skip-children');

function walkExprCtx(node, ctx, cb) {
  if (!node || typeof node !== 'object') return;
  const next = cb(node, ctx);
  if (next === SKIP) return;
  switch (node.kind) {
    case 'binary':
      walkExprCtx(node.left, ctx, cb); walkExprCtx(node.right, ctx, cb); break;
    case 'unary': walkExprCtx(node.operand, node.op === '!' && ctx === 'check' ? 'check' : ctx, cb); break;
    case 'assign': walkExprCtx(node.target, 'drop', cb); walkExprCtx(node.value, ctx, cb); break;
    case 'conditional':
      walkExprCtx(node.test, 'check', cb);
      walkExprCtx(node.cons, ctx, cb); walkExprCtx(node.alt, ctx, cb);
      break;
    case 'member': walkExprCtx(node.object, ctx, cb); break;
    case 'index': walkExprCtx(node.object, ctx, cb); walkExprCtx(node.index, ctx, cb); break;
    case 'call':
      if (node.callee.name === 'require' || node.callee.name === 'assert') {
        (node.args || []).forEach((a, i) => walkExprCtx(a, i === 0 ? 'check' : 'drop', cb));
      } else {
        walkExprCtx(node.callee, ctx, cb);
        for (const a of node.args || []) walkExprCtx(a, ctx === 'check' ? 'normal' : ctx, cb);
      }
      for (const o of node.options || []) walkExprCtx(o.value, 'normal', cb);
      break;
    case 'tuple': for (const it of node.items || []) walkExprCtx(it, ctx, cb); break;
    case 'structLiteral': for (const f of node.fields || []) walkExprCtx(f.value, ctx, cb); break;
    default: break;
  }
}

function eachStatement(stmts, cb) {
  for (const wrapped of stmts) {
    walkStatement(wrapped.stmt, cb);
  }
}

function walkStatement(stmt, cb) {
  if (!stmt) return;
  cb(stmt);
  switch (stmt.kind) {
    case 'block': (stmt.statements || []).forEach(walkStatement.bind(null)); break;
    case 'unchecked': walkStatement(stmt.body, cb); break;
    case 'if':
      walkStatement(stmt.consequent, cb);
      if (stmt.alternate) walkStatement(stmt.alternate, cb);
      break;
    case 'while': walkStatement(stmt.body, cb); break;
    case 'doWhile': walkStatement(stmt.body, cb); break;
    case 'for':
      if (stmt.init) walkStatement(stmt.init, cb);
      walkStatement(stmt.body, cb);
      break;
    case 'try':
      walkStatement(stmt.body, cb);
      (stmt.clauses || []).forEach(walkStatement.bind(null));
      break;
    default: break;
  }
}
// rebind forEach callback above
function walkBlockStatements(stmt, cb) {
  const rec = (s) => walkStatement(s, cb);
  if (stmt.kind === 'block') (stmt.statements || []).forEach(rec);
  else rec(stmt);
}

function isLowLevelCall(expr, set = ALL_LOW_LEVEL) {
  return expr && expr.kind === 'call' &&
    expr.callee && expr.callee.kind === 'member' &&
    set.has(expr.callee.property);
}

// ---- view construction -----------------------------------------------------

class View {
  constructor(desc, registry, linearizedContracts, stateVars, methods, modifiers, freeFunctions, entries) {
    this.desc = desc;
    this.registry = registry;
    this.linearized = linearizedContracts;
    this.stateVars = stateVars;
    this.methods = methods;
    this.modifiers = modifiers;
    this.freeFunctions = freeFunctions;
    this.entries = entries;
    this._modifierPieces = new Map();
  }

  resolveMethod(name, arity) {
    const m = this.methods.get(methodKey(name, arity));
    if (m) return m;
    return this.freeFunctions.get(methodKey(name, arity)) || null;
  }

  // Statements of a method with applied modifiers inlined (placeholder _;
  // marks where the wrapped body executes). Origin annotations record
  // where each statement is textually defined.
  effectiveStatements(desc) {
    const node = desc.node;
    if (!node.body) return [];
    const own = node.body.statements.map((stmt) => ({ stmt, origin: desc }));
    let composed = own;
    for (const modName of node.modifiers || []) {
      const pieces = this.modifierPieces(modName);
      if (!pieces) continue;
      composed = [...pieces.pre, ...composed, ...pieces.post];
    }
    return composed;
  }

  modifierPieces(name) {
    if (this._modifierPieces.has(name)) return this._modifierPieces.get(name);
    const mod = this.modifiers.get(name);
    if (!mod) { this._modifierPieces.set(name, null); return null; }
    this._modifierPieces.set(name, undefined); // recursion guard
    const stmts = mod.node.body ? mod.node.body.statements : [];
    const split = [[], []];
    let part = 0;
    const take = (list, origin) => list.forEach((s) => split[part].push({ stmt: s, origin }));
    for (const s of stmts) {
      if (s.kind === 'placeholder') { part = 1; continue; }
      if (s.kind === 'block' || s.kind === 'unchecked') {
        // Modifiers rarely branch around _; keep linear order by depth-first.
      }
      split[part].push({ stmt: s, origin: mod });
    }
    void take;
    // Inline modifiers applied to this modifier itself.
    let pre = split[0];
    let post = split[1];
    for (const innerName of mod.node.modifiers || []) {
      const inner = this.modifierPieces(innerName);
      if (!inner) continue;
      pre = [...inner.pre, ...pre];
      post = [...post, ...inner.post];
    }
    const pieces = { pre, post };
    this._modifierPieces.set(name, pieces);
    return pieces;
  }
}

export class Registry {
  constructor(parsedFiles) {
    this.files = parsedFiles; // [{file, ast}]
    this.contractByName = new Map();
    this.allContracts = [];
    this.freeFunctions = new Map();

    for (const { file, ast } of parsedFiles) {
      for (const contract of ast.contracts) {
        const entry = { file, contract };
        this.allContracts.push(entry);
        if (!this.contractByName.has(contract.name)) this.contractByName.set(contract.name, []);
        this.contractByName.get(contract.name).push(entry);
      }
      for (const fn of ast.freeFunctions || []) {
        const arity = (fn.params || []).length;
        const desc = { ...descriptorFor(fn, file, null, arity), node: fn };
        this.freeFunctions.set(methodKey(fn.name, arity), desc);
      }
    }
  }

  resolveBaseName(name, fromFile) {
    const sameFile = (this.contractByName.get(name) || []).find((c) => c.file === fromFile);
    if (sameFile) return sameFile;
    const any = (this.contractByName.get(name) || [])[0];
    return any || null;
  }

  buildViews() {
    const views = [];
    for (const entry of this.allContracts) {
      if (entry.contract.kind === 'library') {
        // Libraries participate as callees; also build a view so their
        // internal methods can be reached when called.
      }
      views.push(this.buildView(entry));
    }
    return views;
  }

  buildView(entry) {
    const { file, contract } = entry;
    // Linearization: most-derived first, DFS over declared bases.
    const ordered = [];
    const seen = new Set();
    const visit = (f, c) => {
      const k = `${f}::${c.name}`;
      if (seen.has(k)) return;
      seen.add(k);
      ordered.push({ file: f, contract: c });
      for (const baseName of c.bases || []) {
        const base = this.resolveBaseName(baseName, f);
        if (base) visit(base.file, base.contract);
      }
    };
    visit(file, contract);

    const methods = new Map();
    const modifiers = new Map();
    const stateVars = new Map();
    for (const { file: f, contract: c } of ordered) {
      for (const node of c.nodes || []) {
        if (node.functionKind === 'modifier') {
          if (!modifiers.has(node.name)) {
            const arity = (node.params || []).length;
            modifiers.set(node.name, { file: f, contract: c.name, name: node.name, kind: 'modifier', arity, node });
          }
          continue;
        }
        const arity = (node.params || []).length;
        const name = node.functionKind === 'function' ? node.name : node.functionKind;
        const key = methodKey(name, arity);
        if (!methods.has(key)) {
          methods.set(key, { ...descriptorFor(node, f, c.name, arity), node });
        }
      }
      for (const sv of c.stateVariables || []) {
        if (!stateVars.has(sv.name)) {
          stateVars.set(sv.name, {
            file: f, contract: c.name, name: sv.name, kind: 'stateVariable',
            visibility: sv.visibility, node: sv,
          });
        }
      }
    }

    const entries = [];
    const isLibrary = contract.kind === 'library';
    if (!isLibrary) {
      for (const m of methods.values()) {
        if (m.kind === 'constructor' || m.kind === 'fallback' || m.kind === 'receive') {
          entries.push(m);
        } else if (m.kind === 'function' && (m.visibility === 'public' || m.visibility === 'external')) {
          entries.push(m);
        }
      }
      for (const sv of stateVars.values()) {
        if (sv.visibility === 'public') {
          entries.push({ file: sv.file, contract: sv.contract, name: sv.name, kind: 'getter', arity: 0, node: null });
        }
      }
    }

    const desc = { file, contract: contract.name, name: contract.name, kind: 'contract', arity: 0 };
    return new View(desc, this, ordered, stateVars, methods, modifiers, this.freeFunctions, entries);
  }
}

// ---- reachability ----------------------------------------------------------

function collectEdges(view, desc) {
  // Internal calls made anywhere in the effective (modifier-inlined) body.
  const edges = [];
  const seen = new Set();
  const add = (target) => {
    if (!target) return;
    const k = descKey(target);
    if (!seen.has(k)) { seen.add(k); edges.push(target); }
  };

  let wrapped;
  try {
    wrapped = view.effectiveStatements(desc);
  } catch (e) {
    wrapped = desc.node.body ? desc.node.body.statements.map((s) => ({ stmt: s, origin: desc })) : [];
  }

  eachStatement(wrapped, (stmt) => {
    const exprs = statementExpressions(stmt);
    for (const expr of exprs) {
      walkExpr(expr, (n) => {
        if (n.kind !== 'call') return;
        const callee = n.callee;
        const argc = (n.args || []).length;
        if (callee.kind === 'ident') {
          if (BUILTIN_CALLS.has(callee.name)) return;
          add(view.resolveMethod(callee.name, argc));
        } else if (callee.kind === 'member' && callee.object.kind === 'ident') {
          if (callee.object.name === 'super') {
            // Resolve against bases after the current contract in the linearization.
            let started = false;
            for (const { contract: c } of view.linearized) {
              if (!started) {
                if (c.name === desc.contract && _fileOf(view, desc) === desc.file) started = true;
                continue;
              }
              const found = (c.nodes || []).find(
                (fn) => (fn.functionKind === 'function' ? fn.name : fn.functionKind) === callee.property &&
                  (fn.params || []).length === argc);
              if (found) {
                add({ ...descriptorFor(found, _fileOfNode(view, c, found), c.name, argc), node: found });
                return;
              }
            }
          } else if (view.registry.contractByName.has(callee.object.name)) {
            // Explicitly qualified internal call C.foo()
            add(view.resolveMethod(callee.property, argc));
          }
        }
      });
    }
  });

  // Constructors implicitly run linearized base constructors.
  if (desc.kind === 'constructor') {
    let passedSelf = false;
    for (const { file: f, contract: c } of view.linearized) {
      if (!passedSelf) {
        if (c.name === desc.contract) passedSelf = true;
        continue;
      }
      const baseCtor = (c.nodes || []).find((fn) => fn.functionKind === 'constructor');
      if (baseCtor) {
        add({ ...descriptorFor(baseCtor, f, c.name, (baseCtor.params || []).length), node: baseCtor });
      }
    }
  }
  return edges;
}

function _fileOf(view, desc) { return desc.file; }
function _fileOfNode(view, contract, node) {
  const hit = view.linearized.find((l) => l.contract === contract);
  return hit ? hit.file : view.desc.file;
}

function statementExpressions(stmt) {
  const out = [];
  switch (stmt.kind) {
    case 'expression': if (stmt.expr) out.push(stmt.expr); break;
    case 'varDecl': if (stmt.initializer) out.push(stmt.initializer); break;
    case 'return': if (stmt.expr) out.push(stmt.expr); break;
    case 'if': out.push(stmt.test);
      out.push(...statementExpressions(stmt.consequent || {}));
      if (stmt.alternate) out.push(...statementExpressions(stmt.alternate));
      break;
    case 'while': case 'doWhile': out.push(stmt.test); break;
    case 'for':
      if (stmt.test) out.push(stmt.test);
      if (stmt.update) out.push(stmt.update);
      break;
    case 'emit': out.push(stmt.expr); break;
    case 'try':
      out.push(stmt.externalCall);
      break;
    default: break;
  }
  return out.filter(Boolean);
}

function computeReachability(view) {
  // result: Map descKey -> Map entryKey -> chain (array of descriptors)
  const result = new Map();
  const ensure = (k) => {
    if (!result.has(k)) result.set(k, new Map());
    return result.get(k);
  };

  const allMethods = [...view.methods.values()];
  for (const entry of view.entries) {
    if (!entry.node) continue; // getter, no body
    const startChain = [stripNode(entry)];
    const queue = [{ desc: entry, chain: startChain }];
    const visited = new Set([descKey(entry)]);
    ensure(descKey(entry)).set(entryKey(entry), startChain);
    while (queue.length) {
      const { desc, chain } = queue.shift();
      const edges = collectEdges(view, desc);
      for (const target of edges) {
        const tk = descKey(target);
        if (visited.has(tk)) {
          // still record a (possibly equally short) entry path
          ensure(tk);
          continue;
        }
        visited.add(tk);
        const newChain = [...chain, stripNode(target)];
        const slot = ensure(tk);
        if (!slot.has(entryKey(entry)) || slot.get(entryKey(entry)).length > newChain.length) {
          slot.set(entryKey(entry), newChain);
        }
        queue.push({ desc: target, chain: newChain });
      }
    }
  }

  // unreachable methods get no entry map
  for (const m of allMethods) {
    if (!result.has(descKey(m))) result.set(descKey(m), new Map());
  }
  return result;
}

function stripNode(d) {
  return { file: d.file, contract: d.contract, name: d.name, kind: d.kind };
}

// ---- rule 1: tainted delegatecall target -----------------------------------

function rootIdent(expr) {
  let e = expr;
  while (e) {
    if (e.kind === 'ident') return e.name;
    if (e.kind === 'member') e = e.object;
    else if (e.kind === 'index') e = e.object;
    else return null;
  }
  return null;
}

function buildTaintState(view, fnNode) {
  const params = new Set((fnNode.params || []).map((p) => p.name).filter(Boolean));
  const paramCalldata = new Set(
    (fnNode.params || []).filter((p) => p.dataLocation === 'calldata').map((p) => p.name).filter(Boolean));
  const tainted = new Set(params);
  const localDecls = new Set();

  const stmts = fnNode.body ? fnNode.body.statements : [];

  const stateVarTainted = (name) => {
    const sv = view.stateVars.get(name);
    if (!sv) return false;
    const n = sv.node;
    if (n.isConstant || n.isImmutable) return false;
    const t = n.typeNode;
    if (!t) return true;
    if (t.kind === 'typeMapping' || t.kind === 'typeArray') return true;
    if (t.kind === 'typeElementary' && t.path[0] === 'address') return true;
    // User-defined value types / contract types are potentially controllable.
    return !isPrimitiveType(t);
  };

  const refsIn = (expr) => {
    const names = new Set();
    if (expr) walkExpr(expr, (n) => { if (n.kind === 'ident') names.add(n.name); });
    return names;
  };

  const isTaintedExpr = (expr) => {
    if (!expr) return false;
    let bad = false;
    walkExpr(expr, (n) => {
      if (bad) return;
      if (n.kind === 'ident') {
        if (tainted.has(n.name)) { bad = true; return; }
        if (n.name === 'msg' || n.name === 'tx') return;
        if (stateVarTainted(n.name)) { bad = true; return; }
      }
      if (n.kind === 'member' && n.object.kind === 'ident') {
        if (n.object.name === 'msg' && (n.property === 'sender' || n.property === 'data')) bad = true;
        if (n.object.name === 'tx' && n.property === 'origin') bad = true;
      }
    });
    return bad;
  };

  // fixed point over local declarations / assignments
  let changed = true;
  const scan = () => {
    for (const s of stmts) {
      walkStatement(s, (st) => {
        if (st.kind === 'varDecl' && st.initializer && isTaintedExpr(st.initializer)) {
          for (const nm of st.names || []) {
            localDecls.add(nm);
            if (!tainted.has(nm)) { tainted.add(nm); changed = true; }
          }
        }
        if (st.kind === 'expression' && st.expr && st.expr.kind === 'assign') {
          const a = st.expr;
          const names = lvalueNames(a.target);
          if (a.op === '=' ? isTaintedExpr(a.value) : isTaintedExpr(a.value) || isTaintedExpr(a.target)) {
            for (const nm of names) {
              if (!tainted.has(nm)) { tainted.add(nm); changed = true; }
            }
          }
        }
      });
    }
    void refsIn; void paramCalldata;
  };
  let guard = 0;
  while (changed && guard++ < 20) { changed = false; scan(); }
  return { isTaintedExpr };
}

function lvalueNames(expr) {
  if (!expr) return [];
  if (expr.kind === 'ident') return [expr.name];
  if (expr.kind === 'member' || expr.kind === 'index') return lvalueNames(expr.object);
  if (expr.kind === 'tuple') return (expr.items || []).flatMap(lvalueNames);
  return [];
}

function delegateTarget(callExpr) {
  // member object is the target; address(x) cast unwraps to x.
  const obj = callExpr.callee.object;
  if (obj.kind === 'call' && obj.callee.kind === 'ident' &&
      obj.callee.name === 'address' && (obj.args || []).length === 1) {
    return obj.args[0];
  }
  return obj;
}

function runDelegatecallRule(view, desc, wrapped) {
  const findings = [];
  const { isTaintedExpr } = buildTaintState(view, desc.node);
  eachStatement(wrapped, (stmt, origin) => {
    for (const expr of statementExpressions(stmt)) {
      walkExpr(expr, (n) => {
        if (!isLowLevelCall(n, DELEGATE_CALLS)) return;
        const target = delegateTarget(n);
        if (isTaintedExpr(target)) {
          const mem = n.callee;
          findings.push({
            ruleId: 'DELEGATECALL_UNTRUSTED_TARGET',
            origin: origin || desc,
            location: locFromTo(target.loc, mem.propertyLoc),
            targetName: rootIdent(target),
          });
        }
      });
    }
  });
  return findings;
}

// ---- rule 2: unchecked external call result --------------------------------

function isRevertCall(n) {
  if (n.kind !== 'call' || n.callee.kind !== 'ident') return false;
  return n.callee.name === 'revert' || n.callee.name === 'throw';
}

function runUncheckedCallRule(view, desc, wrapped) {
  const findings = [];
  const bindings = []; // {name, call, index}

  wrapped.forEach(({ stmt }, idx) => {
    analyzeStatement(stmt, idx);
  });

  function recordUnchecked(callNode) {
    findings.push({
      ruleId: 'UNCHECKED_EXTERNAL_CALL',
      origin: desc,
      location: memberSpan(callNode),
      prop: callNode.callee.property,
    });
  }

  function analyzeStatement(stmt, idx) {
    switch (stmt.kind) {
      case 'block': (stmt.statements || []).forEach((s, i) => analyzeStatement(s, idx)); break;
      case 'unchecked': analyzeStatement(stmt.body, idx); break;
      case 'if':
        walkExprCtx(stmt.test, 'check', lowLevelCollector());
        if (stmt.consequent) analyzeStatement(stmt.consequent, idx);
        if (stmt.alternate) analyzeStatement(stmt.alternate, idx);
        break;
      case 'while': case 'doWhile':
        walkExprCtx(stmt.test, 'check', lowLevelCollector());
        analyzeStatement(stmt.body, idx);
        break;
      case 'for':
        if (stmt.init) analyzeStatement(stmt.init, idx);
        if (stmt.test) walkExprCtx(stmt.test, 'check', lowLevelCollector());
        if (stmt.update) walkExprCtx(stmt.update, 'normal', lowLevelCollector(idx));
        analyzeStatement(stmt.body, idx);
        break;
      case 'return':
        if (stmt.expr) walkExprCtx(stmt.expr, 'drop', lowLevelCollector(idx));
        break;
      case 'varDecl': {
        if (!stmt.initializer) break;
        const init = stmt.initializer;
        if (isLowLevelCall(init, LOW_LEVEL_CALLS)) {
          const firstName = (stmt.components || [])[0];
          if (firstName && firstName.name && init.callee.property !== 'transfer') {
            bindings.push({ name: firstName.name, call: init, index: idx });
          } else recordUnchecked(init);
        } else {
          walkExprCtx(init, 'normal', lowLevelCollector(idx));
        }
        break;
      }
      case 'expression': {
        const e = stmt.expr;
        if (!e) break;
        if (e.kind === 'assign' && isLowLevelCall(e.value, LOW_LEVEL_CALLS)) {
          if (e.op === '=') {
            const names = lvalueNames(e.target);
            if (names.length && e.value.callee.property !== 'transfer') {
              bindings.push({ name: names[0], call: e.value, index: idx });
              break;
            }
          }
          recordUnchecked(e.value);
          break;
        }
        if (e.kind === 'binary' && (e.op === '||' || e.op === '&&')) {
          const sides = flattenBinary(e, e.op);
          const reverts = sides.some((s) => {
            let found = false;
            walkExpr(s, (n) => { if (isRevertCall(n)) found = true; });
            return found;
          });
          if (reverts) {
            for (const s of sides) {
              if (!sidesReverts(s)) walkExprCtx(s, 'check', lowLevelCollector());
            }
            break;
          }
        }
        if (e.kind === 'unary' && e.op === '!') {
          // !x.send() as a bare statement does not enforce anything.
          walkExprCtx(e.operand, 'normal', lowLevelCollector(idx));
          break;
        }
        walkExprCtx(e, 'normal', lowLevelCollector(idx));
        break;
      }
      case 'try':
        walkExprCtx(stmt.externalCall, 'normal', lowLevelCollector(idx));
        walkBlockStatements(stmt.body, (s) => {});
        (stmt.clauses || []).forEach((c) => walkBlockStatements(c, () => {}));
        // analyze bodies too
        analyzeStatement(stmt.body, idx);
        (stmt.clauses || []).forEach((c) => analyzeStatement(c, idx));
        break;
      default:
        for (const expr of statementExpressions(stmt)) {
          walkExprCtx(expr, 'normal', lowLevelCollector(idx));
        }
    }
  }

  function sidesReverts(side) {
    let found = false;
    walkExpr(side, (n) => { if (isRevertCall(n)) found = true; });
    return found;
  }

  function lowLevelCollector() {
    return (n, ctx) => {
      if (isLowLevelCall(n, LOW_LEVEL_CALLS)) {
        if (ctx === 'check') return SKIP; // validated
        recordUnchecked(n);
        return SKIP;
      }
      return undefined;
    };
  }

  function flattenBinary(expr, op) {
    const out = [];
    const rec = (e) => {
      if (e.kind === 'binary' && e.op === op) { rec(e.left); rec(e.right); }
      else out.push(e);
    };
    rec(expr);
    return out;
  }

  // Second pass: bound variables must be used in a later checking context.
  for (const b of bindings) {
    let checked = false;
    for (let i = b.index + 1; i < wrapped.length && !checked; i++) {
      const { stmt } = wrapped[i];
      checked = varCheckedInStatement(stmt, b.name);
    }
    if (!checked) recordUnchecked(b.call);
  }

  // Deduplicate identical locations (a call can be seen once).
  const seen = new Set();
  return findings.filter((f) => {
    const k = f.location.startOffset + ':' + f.location.endOffset;
    if (seen.has(k)) return false;
    seen.add(k);
    return true;
  }).map((f) => ({ ...f, origin: desc }));
}

function varCheckedInStatement(stmt, name) {
  let found = false;
  const cb = (n, ctx) => {
    if (found) return;
    if (ctx === 'check' && n.kind === 'ident' && n.name === name) found = true;
  };
  const scan = (s) => {
    switch (s.kind) {
      case 'if':
        walkExprCtx(s.test, 'check', cb);
        if (s.consequent) rec(s.consequent);
        if (s.alternate) rec(s.alternate);
        break;
      case 'while': case 'doWhile':
        walkExprCtx(s.test, 'check', cb); rec(s.body); break;
      case 'for':
        if (s.test) walkExprCtx(s.test, 'check', cb);
        if (s.init) rec(s.init);
        rec(s.body);
        break;
      case 'expression':
        if (s.expr) {
          const e = s.expr;
          if (e.kind === 'binary' && (e.op === '||' || e.op === '&&')) {
            const sides = [];
            const flatten = (x) => x.kind === 'binary' && x.op === e.op
              ? (flatten(x.left), flatten(x.right)) : sides.push(x);
            flatten(e);
            if (sides.some((sd) => { let r = false; walkExpr(sd, (n) => {
              if (n.kind === 'call' && n.callee.kind === 'ident' &&
                  (n.callee.name === 'revert' || n.callee.name === 'throw')) r = true;
            }); return r; })) {
              for (const sd of sides) walkExprCtx(sd, 'check', cb);
              break;
            }
          }
          walkExprCtx(e, 'normal', cb);
        }
        break;
      case 'return': if (s.expr) walkExprCtx(s.expr, 'drop', cb); break;
      case 'varDecl': if (s.initializer) walkExprCtx(s.initializer, 'normal', cb); break;
      case 'unchecked': rec(s.body); break;
      case 'block': (s.statements || []).forEach(rec); break;
      case 'try':
        walkExprCtx(s.externalCall, 'normal', cb);
        rec(s.body); (s.clauses || []).forEach(rec);
        break;
      default:
        for (const expr of statementExpressions(s)) walkExprCtx(expr, 'normal', cb);
    }
  };
  const rec = (s) => { if (!found) scan(s); };
  rec(stmt);
  return found;
}

function memberSpan(callNode) {
  const mem = callNode.callee;
  return locFromTo(mem.object.loc, mem.propertyLoc);
}

function locFromTo(a, b) {
  return {
    startOffset: a.startOffset,
    endOffset: b.endOffset,
    startLine: a.startLine,
    startColumn: a.startColumn,
    endLine: b.endLine,
    endColumn: b.endColumn,
  };
}

// ---- rule 3: state update after external interaction -----------------------

function isExternalInteraction(view, n) {
  if (n.kind !== 'call') return false;
  // contract creation: new X(...)
  if (n.callee.kind === 'newExpr') return true;
  const callee = n.callee;
  if (callee.kind === 'member') {
    if (ALL_LOW_LEVEL.has(callee.property)) return true;
    const obj = callee.object;
    if (obj.kind === 'ident') {
      if (obj.name === 'super') return false;            // internal dispatch
      if (view.registry.contractByName.has(obj.name)) {
        // Explicitly qualified C.foo() / library internal call.
        const target = view.resolveMethod(callee.property, (n.args || []).length);
        if (target && target.kind === 'function') return false;
      }
    }
    // Any other member call (state var contract, local contract reference,
    // msg.sender, address casts) is a potential external call.
    return true;
  }
  return false;
}

function stateWriteRoot(view, expr) {
  // returns state-var descriptor if this lvalue writes contract storage.
  let e = expr;
  while (e) {
    if (e.kind === 'ident') return view.stateVars.get(e.name) || null;
    if (e.kind === 'member' || e.kind === 'index') { e = e.object; continue; }
    return null;
  }
  return null;
}

function runStateUpdateRule(view, desc, wrapped, isEntry) {
  if (!isEntry || !desc.node.body) return [];
  const findings = [];
  let seenCall = false;
  let fired = false;

  const scanExprForCall = (expr) => {
    if (seenCall) return;
    walkExpr(expr, (n) => { if (isExternalInteraction(view, n)) seenCall = true; });
  };

  for (const { stmt, origin } of wrapped) {
    // First detect interactions anywhere in the statement (incl. RHS).
    for (const expr of statementExpressions(stmt)) scanExprForCall(expr);

    if (!seenCall || fired) continue;

    let writeLoc = null;
    let writeName = null;
    walkStatement(stmt, (st) => {
      if (fired || writeLoc) return;
      if (st.kind === 'expression' && st.expr) {
        const e = st.expr;
        if (e.kind === 'assign') {
          const sv = stateWriteRoot(view, e.target);
          if (sv) { writeLoc = e.target.loc; writeName = sv.name; }
        } else if (e.kind === 'unary' && (e.op === '++' || e.op === '--')) {
          const sv = stateWriteRoot(view, e.operand);
          if (sv) { writeLoc = e.operand.loc; writeName = sv.name; }
        } else if (e.kind === 'unary' && e.op === 'delete') {
          const sv = stateWriteRoot(view, e.operand);
          if (sv) { writeLoc = e.operand.loc; writeName = sv.name; }
        }
      }
    });

    if (writeLoc) {
      fired = true;
      findings.push({
        ruleId: 'STATE_UPDATE_AFTER_CALL',
        origin: origin || desc,
        location: writeLoc,
        stateVar: writeName,
      });
    }
  }
  return findings;
}

// ---- driver ----------------------------------------------------------------

export function analyze(parsedFiles) {
  const registry = new Registry(parsedFiles);
  const views = registry.buildViews();

  // key -> finding accumulator
  const acc = new Map();

  const addFindings = (rawList, view, desc, reach) => {
    for (const raw of rawList) {
      const key = `${raw.ruleId}:${raw.origin.file}:${raw.location.startOffset}`;
      let f = acc.get(key);
      if (!f) {
        f = {
          ruleId: raw.ruleId,
          severity: RULES[raw.ruleId].severity,
          file: raw.origin.file,
          location: raw.location,
          detail: raw,
          entries: new Map(), // entryKey -> {entry, chain}
        };
        acc.set(key, f);
      }
      const reachMap = reach.get(descKey(raw.origin.kind === 'modifier' ? modifierOwner(raw.origin) : raw.origin)) ||
        reach.get(descKey(desc)) || new Map();
      // Modifier-originated findings inherit the reachability of the
      // enclosing method (modifiers are inlined).
      const effective = (raw.origin.kind === 'modifier') ? reach.get(descKey(desc)) : reachMap;
      if (effective) {
        for (const [ek, chain] of effective.entries()) {
          const existing = f.entries.get(ek);
          if (!existing || existing.chain.length > chain.length) f.entries.set(ek, { chain });
        }
      }
    }
  };

  function modifierOwner() { return null; }

  for (const view of views) {
    const reach = computeReachability(view);
    for (const desc of view.methods.values()) {
      if (!desc.node || !desc.node.body) continue;
      const wrapped = view.effectiveStatements(desc);
      const isEntry = view.entries.some((e) => e.node && descKey(e) === descKey(desc));

      addFindings(runDelegatecallRule(view, desc, wrapped), view, desc, reach);
      addFindings(runUncheckedCallRule(view, desc, wrapped), view, desc, reach);
      addFindings(runStateUpdateRule(view, desc, wrapped, isEntry), view, desc, reach);
    }
  }

  return finalize(acc);
}

function finalize(acc) {
  const findings = [];
  for (const f of acc.values()) {
    const entryPoints = [];
    const chains = [];
    const entriesArr = [...f.entries.values()];
    entriesArr.sort((a, b) => a.chain.length - b.chain.length);
    for (const { chain } of entriesArr) {
      const entry = chain[0];
      if (!entryPoints.some((e) => e.name === entry.name && e.contract === entry.contract && e.kind === entry.kind)) {
        entryPoints.push(entry);
        chains.push(chain);
      }
    }
    const reachable = entryPoints.length > 0;
    const d = f.detail;
    let message;
    if (d.ruleId === 'DELEGATECALL_UNTRUSTED_TARGET') {
      message = 'delegatecall 的目标可由不受信来源（函数参数/calldata、msg.sender、tx.origin 或可变状态变量）控制，可能导致任意合约执行';
    } else if (d.ruleId === 'UNCHECKED_EXTERNAL_CALL') {
      message = `底层调用 ${d.prop} 的结果未在同函数后续控制流中检查，调用失败可能被静默忽略`;
    } else {
      message = `公开入口在外部调用/转账之后才写入状态变量 ${d.stateVar}，违反 checks-effects-interactions，存在重入风险`;
    }
    findings.push({
      ruleId: f.ruleId,
      severity: f.severity,
      message,
      location: {
        file: f.file,
        startLine: f.location.startLine,
        startColumn: f.location.startColumn,
        endLine: f.location.endLine,
        endColumn: f.location.endColumn,
      },
      reachable,
      evidence: {
        entryPoints: reachable ? entryPoints : [],
        callChain: reachable ? chains[0] : [],
      },
    });
  }
  return findings;
}

