mkdir -p /tmp/csreal && cat > /tmp/csreal/ReentrancyGuard.sol <<'EOF'
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

interface IERC20 {
    function transfer(address to, uint256 amount) external returns (bool);
}

library SafeTransfer {
    function safeCall(address token, bytes calldata payload) internal returns (bytes memory) {
        (bool ok, bytes memory ret) = token.call(payload);
        require(ok, "call failed");
        return ret;
    }
}

abstract contract ReentrancyGuard {
    uint256 private constant NOT_ENTERED = 1;
    uint256 private _status = NOT_ENTERED;

    modifier nonReentrant() {
        require(_status == NOT_ENTERED, "reentrant");
        _status = 2;
        _;
        _status = NOT_ENTERED;
    }
}

error Unauthorized();

contract Vault is ReentrancyGuard {
    enum Stage { Open, Closed }

    struct Deposit { address depositor; uint256 amount; }

    mapping(address => uint256) public balanceOf;
    Deposit[] public deposits;
    Stage public stage;
    address public logic;

    event Deposited(address indexed who, uint256 amount);

    using SafeTransfer for address;

    constructor() {
        stage = Stage.Open;
    }

    receive() external payable {}

    function deposit() external payable nonReentrant {
        balanceOf[msg.sender] += msg.value;
        deposits.push(Deposit(msg.sender, msg.value));
        emit Deposited(msg.sender, msg.value);
    }

    function withdraw(uint256 amount) external nonReentrant {
        require(balanceOf[msg.sender] >= amount);
        (bool ok, ) = msg.sender.call{value: amount, gas: 50000}("");
        if (!ok) revert Unauthorized();
        balanceOf[msg.sender] -= amount;
    }

    function proxyCall(bytes calldata data) external {
        (bool ok, ) = logic.delegatecall(data);
        require(ok);
    }

    function tryWithdraw(address token, uint256 amount) external {
        try IERC20(token).transfer(address(this), amount) returns (bool) {
            balanceOf[msg.sender] -= amount;
        } catch {
            revert();
        }
    }

    function uncheckedBlock(uint256 i) public {
        unchecked { i += 1; }
        msg.sender.transfer(i);
    }
}
EOF
