// SPDX-License-Identifier: MIT
pragma solidity ^0.8.23;

type UFixed is uint256;

using {add} for UFixed global;

function add(UFixed a, UFixed b) pure returns (UFixed) {
    return UFixed.wrap(UFixed.unwrap(a) + UFixed.unwrap(b));
}

interface IGem {
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
}

library Lib {
    function doThing(IGem gem, address f, address t, uint256 amt) internal returns (bool) {
        try gem.transferFrom(f, t, amt) returns (bool ok) {
            return ok;
        } catch Error(string memory reason) {
            revert(reason);
        } catch (bytes memory lowLevelData) {
            revert("low");
        } catch Panic(uint256 code) {
            revert("panic");
        } catch {
            revert();
        }
    }
